# apply_retune_and_run.py — reapplies track fix, then runs a full retune:
#   1. Walk-forward with corrected labels to get baseline matchup LL
#   2. Alpha sweep + T sweep to find best config
#   3. Update predict_next defaults
#   4. Validate against OddsLogic 5-race backtest
import base64, pathlib, subprocess, sys

FILES = {
    'src/features/tracks.py': '',
    'src/scrape/nascar_com.py': '',
}


def main():
    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"wrote {target}")

    import numpy as np, pandas as pd
    from src.scrape.nascar_com import track_type_for

    # Re-classify with corrected labels.
    print("\n=== Step 1: Re-classifying parquets ===")
    races = pd.read_parquet("data/processed/races.parquet")
    entries = pd.read_parquet("data/processed/entries.parquet")
    races["track_type"] = races["track_name"].apply(track_type_for)
    tt_map = dict(zip(races["race_id_short"], races["track_type"]))
    entries["track_type"] = entries["race_id_short"].map(tt_map).fillna(entries["track_type"])
    races.to_parquet("data/processed/races.parquet", index=False)
    entries.to_parquet("data/processed/entries.parquet", index=False)
    print(f"Reclassified. Track type distribution:")
    print(races["track_type"].value_counts())

    # Walk-forward with different alpha values.
    print("\n=== Step 2: Alpha sweep with corrected labels ===")
    from src.eval.backtest_gbm_walkforward import backtest_gbm_walkforward, summarize_wf

    sessions = pd.read_parquet("data/processed/sessions.parquet")
    loopstats = pd.read_parquet("data/processed/loopstats.parquet")
    laptimes = pd.read_parquet("data/processed/laptimes.parquet")
    TIGHT_REG = {"num_leaves": 31, "min_data_in_leaf": 25, "lambda_l2": 2.0}

    best_alpha = 0.85
    best_ll = float("inf")
    alpha_results = {}
    for alpha in [0.70, 0.85, 1.0]:
        print(f"\n--- alpha={alpha} ---")
        out = backtest_gbm_walkforward(
            races, entries, sessions, loopstats, laptimes=laptimes,
            initial_train_races=36, retrain_every_n=10,
            calib_window=25, recalibrate_every_n=10,
            ensemble_alpha=alpha, n_samples=3000,
            gbm_fit_kwargs=TIGHT_REG,
            n_ensemble=5,  # smaller for speed during retune
        )
        s = summarize_wf(out["metrics"])
        ll = s.loc["ALL", "matchup_logloss"]
        alpha_results[alpha] = ll
        print(f"  matchup_ll={ll:.4f}")
        if ll < best_ll:
            best_ll = ll
            best_alpha = alpha

    print(f"\nBest alpha (walk-forward): {best_alpha} -> matchup_ll {best_ll:.4f}")

    # Update predict_next defaults if the best alpha is different from current 0.85.
    if abs(best_alpha - 0.85) > 0.01:
        print(f"\n=== Step 3: Updating predict_next default alpha to {best_alpha} ===")
        p = pathlib.Path("src/cli/predict_next.py")
        s = p.read_text()
        s = s.replace("ALPHA = 0.85", f"ALPHA = {best_alpha}")
        p.write_text(s)
        print("  updated")
    else:
        print(f"\nBest alpha ({best_alpha}) matches current default; no change needed.")

    # Validation.
    print("\n=== Step 4: OddsLogic validation with retuned config ===")
    print("Now run:  python backtest_oddslogic_v4.py")
    print("to see the 5-race matchup log-loss with the retuned model.")

if __name__ == "__main__":
    main()
